(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[584],{1295:function(e,t,n){(window.__NEXT_P=window.__NEXT_P||[]).push(["/Value",function(){return n(2008)}])},2008:function(e,t,n){"use strict";n.r(t),n.d(t,{useTOC:function(){return a}});var r=n(5893),i=n(7812),s=n(4399),l=n(9299);function a(e){return[{value:"3.1.企业智能体的价值",id:"31企业智能体的价值",depth:2},{value:"3.2.企业智能体建设的机遇",id:"32企业智能体建设的机遇",depth:2},{value:"3.3.企业智能体建设的挑战",id:"33企业智能体建设的挑战",depth:2}]}t.default=(0,i.c)(function(e){let{toc:t=a(e)}=e,n={h1:"h1",h2:"h2",li:"li",p:"p",strong:"strong",ul:"ul",...(0,l.a)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(n.h1,{children:"3.企业智能体的价值与建设挑战"}),"\n",(0,r.jsx)(n.h2,{id:t[0].id,children:t[0].value}),"\n",(0,r.jsx)(n.p,{children:"企业智能体一旦能够投产并产生数字生产力，智能体对于企业的价值就会很快呈现出来。这种价值主要体现在以下三个方面："}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"让任务完成效率更高"}),"：这是大家最容易想到的一个价值方向。当前企业内部存在大量传统数字化技术难以自动化的任务，这些任务普遍都依靠员工手工执行并且容易出错。智能体凭借在自然语言交互与智能决策上的巨大优势，在自动化此类任务时有着明显效率优势；"]}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"让任务完成质量更高"}),"：由于大模型的幻觉问题，人们常认为智能体完成任务的质量不及人类，但实际情况洽洽相反。一个设计良好的智能体完成任务的质量下限很多时候比人类员工完成的质量下限要高，且更为稳定。尤其是在需要大量人力去完成大量同样任务的时候，人类员工由于知识背景、培训程度、岗位技能的差异，导致完成任务的上下限差异幅度大，不容易管理。相反，设计良好的智能体能够获得比人类更完整知识背景，更稳定推理质量，再辅助合适的质量检查和反思逻辑，其输出质量的下限能够很好地得以保障。"]}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"让员工资源配置更优"}),"：虽然智能体也被称之为“硅基员工”，但它和人类相比目前还缺乏面对复杂任务的理解力和解决问题的创新力。而这方面正是人类员工可以给企业带来的最大价值。当前，由于人类员工被大量困在前面提到的依赖人的流程性工作，导致他们并不能把自身精力投入到更重要的事情，比如提升客户满意度，优化当前复杂工艺，尝试更好创意等等。一旦智能体被企业普遍采纳，企业员工将会把自身精力主要投入到这些对于企业核心竞争力更为重要的地方。"]}),"\n"]}),"\n"]}),"\n",(0,r.jsx)(n.p,{children:"目前，不仅智能体对于企业的价值在日益清晰，而且企业构建智能体的机遇也全面打开。这种机遇的到来得益于整个生成式 AI 行业过去几年的快速迭代。"}),"\n",(0,r.jsx)(n.h2,{id:t[1].id,children:t[1].value}),"\n",(0,r.jsx)(n.p,{children:"毫无疑问，生成式 AI 的发展速度是整个 AI 发生历史中最快的。眼下，我们完全可以用日新月异来描述这个行业的全面进步。当然，这种进步给企业带来的最直接的机遇就是智能体建设的窗口期全面打开。具体来说，这主要体现在以下几个方面："}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"大模型能力在快速提升"}),"。得益于头部企业大规模的 AI 基础设施投入以及 Scaling Law 法则带来的红利快速兑现，业内主流大模型能力基本每半年甚至更短时间快速迭代一轮。各种基准测试的上限在不断被刷新。部分企业在实践过程中也能明显感知到，模型版本的每一次更新都可以给智能体带来的显著智能化水平提升。"]}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"大模型能力在充分开放"}),"。开源与闭源路线一直是大模型领域争论最激烈的话题。2025 年初 DeepSeek R1 模型的发布让这个争论有了阶段性的结论，那就是开源大模型是主流选择之一。随着国家把人工智能普惠上升为国家战略，国内几乎所有行业头部企业都参与到大模型开源这个浪潮中。而充分竞争的开源大模型格局又会反过来推动开源大模型以不低于（甚至高于）闭源大模型的速度发展。有了高质量的开源大模型后，企业构建智能体的技术门槛和成本门槛都快速下降。无论是自己搭建专属大模型服务还是采纳公有云运营的大模型服务都变得触手可得。"]}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"智能体构建生态在快速成熟"}),"。有了高质量开源大模型后，智能体还需要自己的技术和产品生态。这其中包括如 RAG 技术的成熟，MCP 协议的普及以及其他生态技术的发展。当然，企业落地智能体还需要整合好这些技术的产品供应商，无论是智能体构建平台还是开箱即用的垂直智能体都能有效降低企业采纳的门槛。"]}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"社会共识在逐步形成"}),"。得益于 DeepSeek 的爆火，AI 技术在全社会进行了一次及其广泛的认知教育。而随之而来的大量资本与技术投入、企业自身的积极尝试，成功案例的标杆效应，让企业上下对采纳智能体有了更迫切的期待和更开放的心态。"]}),"\n"]}),"\n"]}),"\n",(0,r.jsx)(n.p,{children:"在以上条件逐步形成过程中，企业建设智能体的机遇之门也随之打开。当然，这个过程企业仍然会面临非常多的挑战。"}),"\n",(0,r.jsx)(n.h2,{id:t[2].id,children:t[2].value}),"\n",(0,r.jsx)(n.p,{children:"作为一个变革性技术，智能体对于大部分企业来说都是一个全新的东西。无论是观念的理解还是企业相关能力的建设都非常具有挑战。具体来说可以分成以下几个方面："}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"企业认知挑战（尤其是公司决策层的认知挑战）"}),"：智能体被称之为“数字员工”，是企业未来运营中的一种全新智力来源。这需要公司全员能够理解到这类智力的特点、能力边界以及如何设计数字员工与人类员工之间的协助关系。同时，一种新的智力引入也可能给企业的经营发展带来更多的可能，让原来没法做或者不值得做的事情变得可行，相反也可能瓦解企业目前建立起来的某些核心竞争力。这些都是需要认知层面深入思考的重要问题。"]}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"员工技能挑战"}),"：智能体和企业员工之前遇到的数字化工具有很大不同。首先，员工在构建和使用智能体过程中需要把它当成一个有智力的“数字人”看待，这是员工使用之前数字化员工没遇到过的情形。比如，员工需要理解一个智能体的边界就像你要了解你同事的能力边界一样。面对不同能力的智能体，你需要安排合适它的任务或者以不同方式和这位同事协作（比如，初级智能体你需要主动帮它拆解问题、明确流程，而对于高级智能体你仅需要清晰告知任务内容和要求）。其次，由于生成式 AI 技术还在发展初级阶段，各种技术的迭代仍然非常快，这需要员工保持高频的自我技能迭代。公司也需要给员工在这方面提供充分的培训与赋能。"]}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.strong,{children:"持续运营挑战"}),"：即使企业让智能体成功投产，这也不代表企业就跨过了智能体建设的所有挑战。恰恰相反，智能体投产是企业开始培养“数字员工”的起点。就像我们不会认为人类员工一旦到岗就会自然取得成功，我们希望他到岗后能在真实事情上锻炼自己，提升自己，有必要时再给予培训与赋能，这样他才能成长起来成为一个合格员工。同样，智能体投产也仅仅代表这个“数字员工”已经到岗。虽然数字员工已经有了部分类人的智力，但限于大模型目前都还没有主动的自我学习和迭代能力。智能体仍然需要完全依赖外部帮助他们学习和成长。正因为如此，智能体的持续运营是企业建设智能体的核心挑战之一。在这个过程中常见问题表现为智能体使用限制多，智能体输出质量不稳定以及智能体执行效率低。面对这些运营问题，一方面企业要让全员能够持积极包容的态度对待（类似对待新员工），另外一方面企业要安排专门的人员基于真实反馈持续优化和改进。\n虽然企业在落地智能体时仍然存在不少现实挑战，但考虑到智能体对于企业的巨大价值，企业仍然值得积极去尝试。在尝试过程中，务实的方式方法与合适的路径选择常常成为关键所在。"]}),"\n"]}),"\n"]})]})},"/Value",{filePath:"pages/Value.mdx",timestamp:1761562066e3,pageMap:s.v,frontMatter:{},title:"3.企业智能体的价值与建设挑战"},"undefined"==typeof RemoteContent?a:RemoteContent.useTOC)},4399:function(e,t,n){"use strict";n.d(t,{v:function(){return r}});let r=[{data:{index:{title:"1. 引言"},Development:{title:"2.生成式 AI 的发展浪潮与智能体的兴起"},Value:{title:"3.企业智能体的价值与建设挑战"},Implementation:{title:"4.企业智能体的落地公式"},Scenario:{title:"5.企业智能体的场景选择"},Role:{title:"6.企业智能体的角色定位"},Approach:{title:"7.企业智能体的实现范式"},Path:{title:"8.企业智能体的落地路径"},Construction:{title:"9.企业智能体的建设内容与组织支持"},Technologies:{title:"10.企业智能体建设的关键技术"},MaxKB:{title:"11.MaxKB：企业级智能体平台"},cases:{title:"12.企业智能体建设成功案例"},Reference:{title:"13.参考链接"},contact:{title:"14. 联系我们"}}},{name:"Approach",route:"/Approach",frontMatter:{sidebarTitle:"Approach"}},{name:"cases",route:"/cases",children:[{data:{zgnd:{title:"12.1.中国农业大学构建“小鹉哥”助力师生咨询及科研教学"},dbcjdx:{title:"12.2.东北财经大学构建校园智慧 AI 助理 “小银杏”"},yyx:{title:'12.3.弋阳县政府构建"弋心一意"小助手提升企业群众办事体验和满意度'},zgtm:{title:"12.4.中国土木工程集团构建“财小问”智能体提升财务管理效率"},dslr:{title:"12.5.都市丽人构建“智慧导购”门店销售智能体提升销售业绩"},szt:{title:"12.6.深圳市深圳通有限公司构建 AI 智能体提升客户满意度"},nysb:{title:"12.7.中非经贸合作研究院构建“尼亚萨波”AI 智能体平台"}}},{name:"dbcjdx",route:"/cases/dbcjdx",frontMatter:{sidebarTitle:"Dbcjdx"}},{name:"dslr",route:"/cases/dslr",frontMatter:{sidebarTitle:"Dslr"}},{name:"nysb",route:"/cases/nysb",frontMatter:{sidebarTitle:"Nysb"}},{name:"szt",route:"/cases/szt",frontMatter:{sidebarTitle:"Szt"}},{name:"yyx",route:"/cases/yyx",frontMatter:{sidebarTitle:"Yyx"}},{name:"zgnd",route:"/cases/zgnd",frontMatter:{sidebarTitle:"Zgnd"}},{name:"zgtm",route:"/cases/zgtm",frontMatter:{sidebarTitle:"Zgtm"}}]},{name:"Construction",route:"/Construction",frontMatter:{sidebarTitle:"Construction"}},{name:"contact",route:"/contact",frontMatter:{sidebarTitle:"Contact"}},{name:"Development",route:"/Development",frontMatter:{sidebarTitle:"Development"}},{name:"Implementation",route:"/Implementation",frontMatter:{sidebarTitle:"Implementation"}},{name:"index",route:"/",frontMatter:{sidebarTitle:"Index"}},{name:"MaxKB",route:"/MaxKB",frontMatter:{sidebarTitle:"Maxkb"}},{name:"Path",route:"/Path",frontMatter:{sidebarTitle:"Path"}},{name:"Reference",route:"/Reference",frontMatter:{sidebarTitle:"Reference"}},{name:"Role",route:"/Role",frontMatter:{sidebarTitle:"Role"}},{name:"Scenario",route:"/Scenario",frontMatter:{sidebarTitle:"Scenario"}},{name:"Technologies",route:"/Technologies",frontMatter:{sidebarTitle:"Technologies"}},{name:"Value",route:"/Value",frontMatter:{sidebarTitle:"Value"}}]}},function(e){e.O(0,[812,888,774,179],function(){return e(e.s=1295)}),_N_E=e.O()}]);